import {Stack, Text} from '@primer/react'

import styles from './CounterNumber.module.css'

export type Sentiment = 'positive' | 'negative' | 'neutral'

export type CounterNumberProps = {
  value: string
  label?: string
  size: 'medium' | 'large'
  sentiment?: Sentiment
}

export const CounterNumber = ({value, label, size, sentiment = 'neutral'}: CounterNumberProps) => (
  <Stack align="baseline" direction="horizontal" gap="tight">
    <span className={`${styles.CounterNumber} text-tabular-nums`} data-size={size} data-sentiment={sentiment}>
      {value}
    </span>

    {label && (
      <Text size="medium" className="color-fg-muted">
        {label}
      </Text>
    )}
  </Stack>
)
