import {ChartCard} from '@github-ui/chart-card'
import type {ChartCardProps} from '@github-ui/chart-card'
import {getTickPositions, tooltipFormatter} from './utils/Utility'
import ChartErrorState from './ChartErrorState'

interface AreaChartData {
  id: string
  label: string
  startDate: string
  endDate: string
  value: number
}

interface AreaChartPayload {
  startDate: string
  endDate: string
  data: AreaChartData[]
}

interface AreaChartProps {
  payload: AreaChartPayload
  title: string
  color?: string
  description?: string
  yAxisTitle?: string
  yAxisMax?: number
  size?: ChartCardProps['size']
  headingLevel?: 'h1' | 'h2' | 'h3' | 'h4' | 'h5' | 'h6'
  visibleChartOptions?: boolean
}

function AreaChart({
  payload,
  title,
  color,
  description,
  yAxisTitle,
  yAxisMax,
  size = 'medium',
  headingLevel = 'h2',
  visibleChartOptions = true,
}: AreaChartProps) {
  if (!payload.data || payload.data.length === 0) {
    return <ChartErrorState title={title} description={description} />
  }

  const series = [
    {
      name: title,
      data: payload.data.map(item => [new Date(item.endDate).getTime(), item.value]),
      type: 'area',
      color: color ?? '',
    },
  ]

  return (
    <div className="height-full">
      <ChartCard
        size={size}
        border
        padding="normal"
        visibleControls={false}
        visibleChartOptions={visibleChartOptions}
        className="width-full height-full"
      >
        <ChartCard.Title as={headingLevel}>{title}</ChartCard.Title>
        {description && <ChartCard.Description>{description}</ChartCard.Description>}
        <ChartCard.Chart
          useUTC
          xAxisTitle=""
          yAxisTitle={yAxisTitle ?? ''}
          series={series}
          plotOptions={{
            area: {
              marker: {
                enabled: false,
              },
            },
          }}
          xAxisOptions={{
            type: 'datetime',
            lineWidth: 1,
            gridLineWidth: 1,
            gridLineDashStyle: 'Solid',
            labels: {
              format: '{value:%b %d}',
            },
            minPadding: 0,
            maxPadding: 0,
            tickPositions: getTickPositions(payload.data, 'half'),
          }}
          yAxisOptions={{
            min: 0,
            max: yAxisMax,
            gridLineWidth: 1,
            gridLineDashStyle: 'Solid',
          }}
          overrideOptionsNotRecommended={{
            chart: {
              spacingRight: 2,
            },
          }}
          tooltipOptions={{
            shared: true,
            outside: true,
            formatter: tooltipFormatter((yAxisTitle ?? '').toLowerCase()),
            useHTML: true,
          }}
          type="area"
        />
      </ChartCard>
    </div>
  )
}

export default AreaChart
