import {ChartCard} from '@github-ui/chart-card'

import type {AxisLabelsFormatterContextObject, SeriesOptionsType, XAxisOptions, YAxisOptions} from 'highcharts'

type ScatterChartSeries = {
  name: string
  color: string
  data: Array<[number, number]>
}

type ScatterChartProps = {
  series: ScatterChartSeries[]
  trendLine: ScatterChartSeries
  title: string
  description: string
  xAxisTitle: string
  yAxisTitle: string
  xAxisOptions: XAxisOptions
  yAxisOptions: YAxisOptions
}

const abbreviateThousands = (context: AxisLabelsFormatterContextObject) =>
  Number(context.value) === 0 ? '' : `${Number(context.value) / 1000}k`

export function ScatterChart({
  series,
  trendLine,
  title,
  description,
  xAxisTitle,
  yAxisTitle,
  xAxisOptions,
  yAxisOptions,
}: ScatterChartProps) {
  const chartSeries: SeriesOptionsType[] = [
    ...series.map(({name, color, data}) => ({
      type: 'scatter',
      name,
      color,
      data,
      marker: {symbol: 'square', radius: 4},
    })),
    {
      type: 'line',
      name: trendLine.name,
      color: trendLine.color,
      data: trendLine.data,
      dashStyle: 'Solid',
      lineWidth: 2,
      marker: {enabled: false},
      enableMouseTracking: false,
    },
  ]

  return (
    <ChartCard size="large" border padding="normal" visibleControls={false} visibleChartOptions={false}>
      <ChartCard.Title as="h3">{title}</ChartCard.Title>
      <ChartCard.Description>{description}</ChartCard.Description>
      <ChartCard.Chart
        type="scatter"
        xAxisTitle={xAxisTitle}
        yAxisTitle={yAxisTitle}
        series={chartSeries}
        xAxisOptions={{
          min: 0,
          gridLineWidth: 1,
          gridLineDashStyle: 'Solid',
          lineWidth: 1,
          labels: {formatter: abbreviateThousands},
          ...xAxisOptions,
        }}
        yAxisOptions={{
          min: 0,
          gridLineWidth: 1,
          gridLineDashStyle: 'Solid',
          ...yAxisOptions,
        }}
      />
    </ChartCard>
  )
}
