import {Heading, Stack} from '@primer/react'

import {Card} from './Card'
import {CounterNumber} from './CounterNumber'
import type {Sentiment} from './CounterNumber'

import {MetricTable} from './MetricTable'
import type {Metric} from './MetricTable'

export type MultiplierCardProps = {
  title: string
  multiplier: string
  multiplierLabel: string
  sentiment: Sentiment
  metrics: [Metric, Metric]
}

export const MultiplierCard = ({title, multiplier, multiplierLabel, metrics, sentiment}: MultiplierCardProps) => (
  <Card>
    <Stack gap="cozy">
      <Stack gap="tight">
        <Heading as="h3" className="f5">
          {title}
        </Heading>

        <CounterNumber size="large" value={multiplier} label={multiplierLabel} sentiment={sentiment} />
      </Stack>

      <hr className="my-0" />

      <MetricTable metrics={metrics} />
    </Stack>
  </Card>
)
