import {Flash, Stack} from '@primer/react'

import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'

import {CopilotBlankslate} from '@github-ui/copilot-insights-shared/components/CopilotBlankslate'
import DataDisclaimer from '@github-ui/copilot-insights-shared/components/header/DataDisclaimer'
import {Header} from '@github-ui/copilot-insights-shared/components/header/Header'
import {useQuerySanitizer} from '@github-ui/copilot-insights-shared/hooks/useQuerySanitizer'

import {InsightsSidenavPanel} from '@github-ui/insights-sidenav'

import {AdoptionCohortsSection} from '../sections/AdoptionCohortsSection'
import {AdoptionMultiplierSection} from '../sections/AdoptionMultiplierSection'
import {EngagementTrendsSection} from '../sections/EngagementTrendsSection'
import {IndustryComparisonSection} from '../sections/IndustryComparisonSection'
import {NextStepsSection} from '../sections/NextStepsSection'
import {ValueSection} from '../sections/ValueSection'
import {copilotImpactRoute} from './copilot-impact-route'

export function CopilotImpact() {
  const payload = useRouteQuery(copilotImpactRoute, 'mainQuery')

  const {
    copilotLicenseManagementLink,
    aiControlsLink,
    exportFilesUrl,
    slug,
    businessId,
    orgId,
    canonicalQueryParams,
    displayBlankslate,
    displayError,
    displayNoMatchingResults,
    displayImpactDisclaimer,
    importedDataFilename,
    insightsOptedIn,
    canManageAiControls,
    copilotDisabled,
    canManageCopilotLicenses,
    sidenav,
  } = payload?.data ?? {}

  const isEnterprise = !sidenav

  useQuerySanitizer(canonicalQueryParams)

  const renderCopilotImpactSections = () => {
    if (copilotDisabled)
      return (
        <CopilotBlankslate
          type="welcome"
          dashboardType="impact"
          copilotLicenseManagementLink={copilotLicenseManagementLink}
          testId="copilot-impact-blankslate"
          copilotDisabled={copilotDisabled}
          canManageCopilotLicenses={canManageCopilotLicenses}
        />
      )

    if (insightsOptedIn === false)
      return (
        <CopilotBlankslate
          type="policy-disabled"
          dashboardType="impact"
          aiControlsLink={`${aiControlsLink}#metrics`}
          testId="copilot-impact-policy-disabled"
          canManageAiControls={canManageAiControls}
          canManageCopilotLicenses={canManageCopilotLicenses}
          isEnterprise={isEnterprise}
        />
      )

    if (displayBlankslate)
      return (
        <CopilotBlankslate
          type="welcome"
          dashboardType="impact"
          copilotLicenseManagementLink={copilotLicenseManagementLink}
          testId="copilot-impact-blankslate"
          canManageCopilotLicenses={canManageCopilotLicenses}
          isEnterprise={isEnterprise}
        />
      )

    if (displayError)
      return (
        <CopilotBlankslate
          type="error"
          dashboardType="impact"
          copilotLicenseManagementLink={copilotLicenseManagementLink}
          testId="copilot-impact-error"
          canManageCopilotLicenses={canManageCopilotLicenses}
          isEnterprise={isEnterprise}
        />
      )

    if (displayNoMatchingResults)
      return (
        <CopilotBlankslate
          type="no-matching-results"
          dashboardType="impact"
          testId="copilot-impact-no-matching-results"
          isEnterprise={isEnterprise}
        />
      )

    return (
      <Stack gap="spacious">
        <AdoptionMultiplierSection />
        <AdoptionCohortsSection />
        <ValueSection />
        <EngagementTrendsSection />
        <IndustryComparisonSection />
        <NextStepsSection />
      </Stack>
    )
  }

  const mainContent = (
    <div data-testid="copilot-impact-page" className="d-flex flex-column gap-4 overflow-x-hidden">
      {displayImpactDisclaimer && <DataDisclaimer testId="copilot-impact-disclaimer" />}

      <Header
        title="Copilot impact"
        slug={slug}
        businessId={businessId}
        orgId={orgId}
        exportFilesUrl={exportFilesUrl}
        disableControls={displayBlankslate || displayError || insightsOptedIn === false}
        page="impact"
        isEnterprise={isEnterprise}
      />

      {importedDataFilename && (
        <Flash variant="warning" aria-live="polite" data-testid="imported-data-notice" className="mb-2">
          Displaying data from file: <strong>{importedDataFilename}</strong>
        </Flash>
      )}

      {renderCopilotImpactSections()}
    </div>
  )

  if (!isEnterprise && sidenav)
    return (
      <div data-testid="copilot-impact-with-sidenav" className="d-flex flex-column flex-lg-row flex-content-stretch">
        <InsightsSidenavPanel
          selectedKey="copilot_metrics_impact"
          showDependencies={sidenav.showDependencies}
          showActionsUsageMetrics={sidenav.showActionsUsageMetrics}
          showApi={sidenav.showApi}
          showCopilotUsage={sidenav.showCopilotUsage}
          showCopilotCodeGeneration={sidenav.showCopilotCodeGeneration}
          showCopilotImpact={sidenav.showCopilotImpact}
          urls={sidenav.urls}
        />
        <div className="flex-1 mx-lg-auto tmp-p-4" style={{maxWidth: 1664}}>
          {mainContent}
        </div>
      </div>
    )

  return mainContent
}
