import {Text} from '@primer/react'

import styles from './MetricTable.module.css'

export type Metric = {
  label: string
  value: string
  unit: string
}

export type MetricTableProps = {
  metrics: Metric[]
}

export const MetricTable = ({metrics}: MetricTableProps) => (
  <table className={`${styles.MetricTable} color-fg-muted width-full flex-1`}>
    <thead>
      <tr>
        {metrics.map(({label}) => (
          <Text as="th" key={label} scope="col" size="small" weight="semibold" className="text-left tmp-pb-1">
            {label}
          </Text>
        ))}
      </tr>
    </thead>
    <tbody>
      <tr>
        {metrics.map(({label, value, unit}) => (
          <td key={label}>
            <Text weight="semibold" className="color-fg-default text-tabular-nums">
              {value}
            </Text>{' '}
            <Text size="small">{unit}</Text>
          </td>
        ))}
      </tr>
    </tbody>
  </table>
)
