import styles from './PhaseDot.module.css'

const RADIUS = 6
const DIAMETER = RADIUS * 2

export type PhaseDotProps = {
  phase: 0 | 1 | 2 | 3
}

export const PhaseDot = ({phase}: PhaseDotProps) => (
  <svg
    aria-hidden="true"
    className={`${styles.PhaseDot} shrink-0`}
    data-phase={phase}
    width={DIAMETER}
    height={DIAMETER}
    viewBox={`-${RADIUS} -${RADIUS} ${DIAMETER} ${DIAMETER}`}
  >
    <circle r={RADIUS} />
  </svg>
)
