import {mainQuery} from '@github-ui/react-core/future/main-query'
import {copilotInsightsImpactAppBuilder} from '../config/app-builder'
import type {CopilotUsageRouteResponse} from '@github-ui/copilot-insights-shared/types/copilot-usage-route-types'

// stafftools version of the route
export const stafftoolsCopilotImpactRoute = copilotInsightsImpactAppBuilder.createQueryRouteConfig(
  'stafftoolsCopilotImpactRoute',
  {
    path: '/stafftools/enterprises/:slug/copilot_insights_impact',
    queries: [
      mainQuery<CopilotUsageRouteResponse>({
        queryDeps: ({pathname, searchParams}) => ({
          pathname,
          searchParams: {
            period: searchParams.get('period') || '28d',
          },
        }),
      }),
    ],
  },
)

