import type {ReactNode} from 'react'
import {ChevronDownIcon, ChevronUpIcon} from '@primer/octicons-react'
import {Details, Heading, Label, Stack, Text, useDetails} from '@primer/react'

import styles from './NextStepDetails.module.css'

export type NextStepDetailsProps = {
  title: string
  label?: string
  description?: string
  children: ReactNode
}

export const NextStepDetails = ({title, label, description, children}: NextStepDetailsProps) => {
  const {getDetailsProps, open} = useDetails({closeOnOutsideClick: false})

  return (
    <div className="border rounded-2">
      <Details {...getDetailsProps()} className={styles.NextStepDetails}>
        <Stack as="summary" direction="horizontal" align="start" gap="condensed" padding="normal">
          <Stack className="width-full" gap="tight">
            <Stack direction="horizontal" align="baseline" gap="condensed">
              <Heading as="h3" className="f5">
                {title}
              </Heading>

              {label && <Label>{label}</Label>}
            </Stack>

            {description && (
              <Text className="color-fg-muted" size="small">
                {description}
              </Text>
            )}
          </Stack>

          {open ? <ChevronUpIcon /> : <ChevronDownIcon />}
        </Stack>

        <Stack paddingInline="normal" className="tmp-pb-3">
          {children}
        </Stack>
      </Details>
    </div>
  )
}
