import {Heading, Label, Stack} from '@primer/react'

type SectionHeaderProps = {
  title: string
  description?: string
  badge?: string
}

export const SectionHeader = ({title, description, badge}: SectionHeaderProps) => (
  <Stack as="header" gap="none">
    <Stack direction="horizontal" gap="condensed" align="center">
      <Heading as="h2" className="f3">
        {title}
      </Heading>
      {badge && <Label size="small">{badge}</Label>}
    </Stack>
    {description && <p className="color-fg-muted mb-0">{description}</p>}
  </Stack>
)
