import {Heading, Stack, Text} from '@primer/react'

import {Card} from './Card'
import {CounterNumber} from './CounterNumber'
import {PhaseDot} from './PhaseDot'
import styles from './PhaseCard.module.css'

export type PhaseCardProps = {
  phase: 0 | 1 | 2 | 3
  title: string
  description: string
  value: string
  prMergeTime: string
  users: string
  creditsCostPerUserMonth: string
  commitsPerUserMonth: string
  locPerUserDay: string
  shareOfMergedPrs: string
}

export const PhaseCard = ({
  phase,
  title,
  description,
  value,
  prMergeTime,
  users,
  creditsCostPerUserMonth,
  commitsPerUserMonth,
  locPerUserDay,
  shareOfMergedPrs,
}: PhaseCardProps) => {
  const rows = [
    {label: 'PR merge time', value: prMergeTime},
    {label: '# of users', value: users, isDivider: true},
    {label: 'Commits per user/month', value: commitsPerUserMonth},
    {label: 'LoC per user/day', value: locPerUserDay},
    {label: 'Share of merged PRs', value: shareOfMergedPrs, isDivider: true},
    {label: 'Credits cost per user/month', value: creditsCostPerUserMonth},
  ]

  return (
    <Card>
      <Stack gap="cozy">
        <Stack gap="tight">
          <Stack gap="tight" align="center" direction="horizontal">
            <PhaseDot phase={phase} />
            <Heading as="h3" className="f5">
              {title}
            </Heading>
          </Stack>

          <Text size="small" className="color-fg-muted">
            {description}
          </Text>

          <CounterNumber size="medium" value={value} label="PRs per user/month" />
        </Stack>

        <hr className="my-0" />

        <table className="color-fg-muted width-full">
          <tbody>
            {rows.map(({label, value: rowValue, isDivider}) => (
              <TableRow key={label} label={label} value={rowValue} isDivider={isDivider} />
            ))}
          </tbody>
        </table>
      </Stack>
    </Card>
  )
}

type TableRowProps = {
  label: string
  value: string
  isDivider?: boolean
}

const TableRow = ({label, value, isDivider}: TableRowProps) => (
  <tr className={styles.TableRow} data-divider={isDivider || undefined}>
    <Text as="th" scope="row" size="small" weight="normal" className="text-left">
      {label}
    </Text>
    <Text as="td" size="small" weight="semibold" className="text-right text-tabular-nums tmp-pl-2">
      {value}
    </Text>
  </tr>
)
